cat > /tmp/findcaller.js <<'EOF'
const fs=require("fs");
const path=require("path");
function dumpStrings(buf){
  let out="";
  for(let i=0;i<buf.length;i++){const c=buf[i]; if(c>=32&&c<127) out+=String.fromCharCode(c); else out+="\n";}
  return out.split("\n").filter(s=>s.length>=2);
}
const root="/tmp/logic-extract";
// find every class referencing RepoAuthKt or githubPackagesToken (the caller)
function walk(d){
  for(const e of fs.readdirSync(d,{withFileTypes:true})){
    const p=path.join(d,e.name);
    if(e.isDirectory()) walk(p);
    else if(e.name.endsWith(".class")){
      const buf=fs.readFileSync(p);
      const strs=dumpStrings(buf);
      const caller=strs.filter(s=>/RepoAuthKt|githubPackagesToken/i.test(s));
      const repo=strs.filter(s=>/maven|url|http|repo/i.test(s));
      if(caller.length){
        console.log("== "+p.replace(root,""));
        console.log("   [token-refs] "+[...new Set(caller)].slice(0,10).join(" | "));
      }
    }
  }
}
walk(root);
EOF
